$ErrorActionPreference='Stop';$git='C:\Program Files\Git\cmd\git.exe';$gh=(Get-Command gh.exe -ErrorAction Stop).Source;$project=$PSScriptRoot;&$gh auth status;&$git -C $project push origin main;if($LASTEXITCODE-ne 0){throw 'Falha ao enviar o projeto.'};$old=$ErrorActionPreference;$ErrorActionPreference='Continue';&$gh api --silent repos/paulo-santzs/agent-playpen/pages 2>$null;$exists=$LASTEXITCODE-eq 0;$ErrorActionPreference=$old;if($exists){&$gh api --method PUT repos/paulo-santzs/agent-playpen/pages -f build_type=workflow *> $null}else{&$gh api --method POST repos/paulo-santzs/agent-playpen/pages -f build_type=workflow *> $null};if($LASTEXITCODE-ne 0){throw 'Falha ao ativar Pages.'};Start-Sleep 5;$runId=&$gh run list --repo paulo-santzs/agent-playpen --workflow pages.yml --limit 1 --json databaseId --jq '.[0].databaseId';&$gh run watch $runId --repo paulo-santzs/agent-playpen --exit-status;if($LASTEXITCODE-ne 0){throw 'O Actions falhou.'};Write-Host 'Agent Playpen publicado: https://paulo-santzs.github.io/agent-playpen/'
